/**
 * The types `node/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    PlayerInfoSaveDecodeResult, FindToolExportFs, FindToolExportOptions, FoundToolExport
 * depends    —
 * used by    src/node/decode-save, src/node/find-export, src/node/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

// from decode-save.ts

export type PlayerInfoSaveDecodeResult = {
  parsedRoot: Record<string, unknown>
  wasGzip: boolean
  battleRunCount: number
}

// from find-export.ts

/** The file-system calls the export search makes, replaceable in a test. */
export interface FindToolExportFs {
  readdirSync: (directory: string) => string[]
  statSync: (file: string) => { isFile: () => boolean, mtimeMs: number }
  readFileSync: (file: string) => Uint8Array
}

export interface FindToolExportOptions {
  /** Home folder; defaults to the current user's. */
  home?: string
  /** `process.platform` value; defaults to this machine's. */
  platform?: string
  env?: Record<string, string | undefined>
  fs?: FindToolExportFs
}

export interface FoundToolExport {
  /** Absolute path of the export, or null when none was found. */
  path: string | null
  /** How it was found: the environment variable or the macOS container scan. */
  source: 'env' | 'macos-container' | null
  /** Every place looked, in order, to tell a person where the export was expected. */
  searched: string[]
}
